#!/usr/bin/env node
// The launcher for hello-cli, generated by claude-apps (/ship). Zero dependencies.
//   (no args)        SessionStart hook: enroll once, then pull a build when the channel moved. Quiet unless something changed.
//   --open           Make sure a build is here, then start it (/hello-cli:open). By the build's ship.run.json mode:
//                    a CLI or desktop app runs here; "local" runs its server here at http://hello-cli.localhost:<port>;
//                    "hosted" opens a one-time sign-in link to the web app on the author's server.
//   --stop           Stop the local server this launcher started.
//   --status         One JSON line: who is signed in, which build, which mode, where it runs.
//   --forget         Stop it and delete everything this launcher keeps (sign-in, builds, app data).
//   --feedback       Send the words on stdin as feedback (/hello-cli:feedback).
//   --device-poll    Internal: finish a device-flow sign-in in the background.
import crypto from 'node:crypto'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import net from 'node:net'
import { execFileSync, spawn } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const PROJECT = 'hello-cli'
const SHIP_URL = process.env.SHIP_LAUNCHER_URL || 'https://claude-apps-e2e-cli.fly.dev'
// The author's build-signing public key: a build whose signature does not check out is never unpacked or run.
const SIGNING_PUB = 'MCowBQYDK2VwAyEATEgJG5Lxqxf1LPVnsNT2xJ-XjeGyImw6_PKkcUoVLaY'
const ENROLL_NS = 'ship-enroll-v1' // Fixed here, never taken from the server
// One folder for the hook and the slash commands alike (Claude Code gives hooks CLAUDE_PLUGIN_DATA but not the `!` shell
// of a command, so that variable would split one install into two).
const DATA = process.env.CLAUDE_APPS_DATA || path.join(os.homedir(), '.claude-apps', PROJECT)
const SELF = fileURLToPath(import.meta.url)
fs.mkdirSync(DATA, { recursive: true, mode: 0o700 })
const file = n => path.join(DATA, n)
const read = n => { try { return fs.readFileSync(file(n), 'utf8').trim() } catch { return '' } }
const write = (n, v) => fs.writeFileSync(file(n), v, { mode: 0o600 })
const say = msg => process.stdout.write(JSON.stringify({ systemMessage: `${PROJECT}: ${msg}` }) + '\n')
const installId = () => read('install_id') || (write('install_id', crypto.randomUUID()), read('install_id'))
const current = () => { try { return JSON.parse(read('current.json')) } catch { return null } }

async function api(p, { method = 'GET', body, token = read('token'), timeout = 15000 } = {}) {
  const headers = { 'x-ship-version': current()?.version || '' }
  if (token) headers.authorization = `Bearer ${token}`
  if (body !== undefined) headers['content-type'] = 'application/json'
  const r = await fetch(SHIP_URL + p, { method, headers, body: body === undefined ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(timeout) })
  return { status: r.status, ok: r.ok, r }
}
const json = async p => { const x = await p; return { ...x, data: await x.r.json().catch(() => ({})) } }

// Enrollment, first by SSH signature with a key already on GitHub, then by device code.
function sshCandidates() {
  const out = []
  const opts = { stdio: ['ignore', 'pipe', 'ignore'], timeout: 5000, env: { ...process.env, SSH_ASKPASS_REQUIRE: 'never' } }
  if (process.env.SSH_AUTH_SOCK) {
    try {
      for (const line of execFileSync('ssh-add', ['-L'], opts).toString().split('\n')) {
        if (!/^(ssh-|ecdsa-|sk-)/.test(line)) continue
        const pub = path.join(os.tmpdir(), `ship-${process.pid}-${out.length}.pub`)
        fs.writeFileSync(pub, line + '\n')
        out.push({ pubkey: line.trim(), signWith: pub, tmp: pub })
      }
    } catch { /* No agent, or it is locked */ }
  }
  const dir = path.join(os.homedir(), '.ssh')
  for (const f of fs.existsSync(dir) ? fs.readdirSync(dir) : []) {
    if (!f.endsWith('.pub')) continue
    const priv = path.join(dir, f.slice(0, -4))
    const pubkey = fs.readFileSync(path.join(dir, f), 'utf8').trim()
    if (!fs.existsSync(priv) || out.some(c => c.pubkey.split(' ')[1] === pubkey.split(' ')[1])) continue
    try { execFileSync('ssh-keygen', ['-y', '-P', '', '-f', priv], opts); out.push({ pubkey, signWith: priv }) } catch { /* Has a passphrase and is not in the agent */ }
  }
  return out
}
async function enrollSsh() {
  const cands = sshCandidates()
  try {
    if (!cands.length) return null
    const { data } = await json(api('/enroll/nonce', { method: 'POST', body: {}, token: '' }))
    // The signed text is fixed by this launcher: its namespace, the origin it was built for, and a plain random nonce.
    // A server cannot get a signature over anything else (a git commit, or a nonce from another claude-apps server).
    if (!/^[A-Za-z0-9_-]{16,64}$/.test(String(data.nonce || ''))) return null
    const message = `${ENROLL_NS}\n${new URL(SHIP_URL).origin}\n${data.nonce}`
    for (const c of cands) {
      let signature
      try {
        signature = execFileSync('ssh-keygen', ['-Y', 'sign', '-n', ENROLL_NS, '-f', c.signWith], { input: message, timeout: 8000, stdio: ['pipe', 'pipe', 'ignore'], env: { ...process.env, SSH_ASKPASS_REQUIRE: 'never' } }).toString()
      } catch { continue }
      const v = await json(api('/enroll/verify', { method: 'POST', token: '', body: { nonce: data.nonce, pubkey: c.pubkey, signature, install_id: installId() } }))
      if (v.ok && v.data.token) { write('token', v.data.token); write('user', v.data.user); return v.data.user }
    }
    return null
  } finally { for (const c of cands) if (c.tmp) fs.rmSync(c.tmp, { force: true }) }
}
async function enrollDevice() {
  const pending = (() => { try { return JSON.parse(read('device.json')) } catch { return null } })()
  if (pending && pending.exp > Date.now()) return pending
  const d = await json(api('/enroll/device', { method: 'POST', body: {}, token: '' }))
  if (!d.ok) return null
  const info = { ...d.data, exp: Date.now() + 14 * 60000 }
  write('device.json', JSON.stringify(info))
  spawn(process.execPath, [SELF, '--device-poll'], { detached: true, stdio: 'ignore', env: process.env }).unref()
  return info
}
async function devicePoll() {
  let info
  try { info = JSON.parse(read('device.json')) } catch { return }
  while (Date.now() < info.exp && !read('token')) {
    await new Promise(r => setTimeout(r, (info.interval || 5) * 1000))
    const x = await json(api('/enroll/device', { method: 'POST', token: '', body: { poll: info.poll, install_id: installId() } })).catch(() => null)
    if (x?.ok && x.data.token) { write('token', x.data.token); write('user', x.data.user); break }
    if (x && x.status !== 202 && !x.ok) break
  }
  fs.rmSync(file('device.json'), { force: true })
}
async function ensureToken() {
  if (read('token')) return { ok: true }
  const user = await enrollSsh().catch(() => null)
  if (user) return { ok: true, user, fresh: true }
  const d = await enrollDevice().catch(() => null)
  if (d?.user_code) return { ok: false, msg: `one-time sign-in: enter code ${d.user_code} at ${d.verification_uri} (only needed once)` }
  // No grant matched: say exactly what the author needs. A public key is safe to show and to send.
  const pub = sshCandidates().map(c => c.pubkey)[0]
  return { ok: false, msg: pub ? `not shared with you yet. Ask the author to run /ship share <your GitHub username>, or to paste your public key: /ship share <name> --key "${pub}"`
    : 'not shared with you yet, and this machine has no SSH key to sign in with. Run ssh-keygen -t ed25519 and send the author the line in ~/.ssh/id_ed25519.pub; they run /ship share <name> --key "<that line>"' }
}

function signedByAuthor(sha, sig) {
  try {
    const key = crypto.createPublicKey({ key: Buffer.from(SIGNING_PUB, 'base64url'), format: 'der', type: 'spki' })
    return crypto.verify(null, Buffer.from(`ship-build-v1\n${PROJECT}\n${sha}`), key, Buffer.from(String(sig || ''), 'base64url'))
  } catch { return false }
}
// Builds: the feed names a sha; the archive is checked against it and its signature, then unpacked once.
async function update() {
  const feed = await json(api('/feed'))
  if (feed.status === 401) { fs.rmSync(file('token'), { force: true }); return { msg: 'access was removed by the author' } }
  if (!feed.ok || !feed.data.sha) return { msg: feed.ok ? 'no build has been shipped yet' : `server answered ${feed.status}` }
  const have = current()
  if (have?.sha === feed.data.sha && fs.existsSync(file('app-' + have.sha))) return { same: true, version: have.version }
  // A build in R2 comes as a presigned URL (no token sent there); the sha and signature checks below hold either way.
  const res = /^https?:\/\//.test(feed.data.url) ? await fetch(feed.data.url, { signal: AbortSignal.timeout(120000) }).then(r => ({ ok: r.ok, status: r.status, r }))
    : await api(feed.data.url, { timeout: 120000 })
  if (!res.ok) return { msg: `could not fetch build (${res.status})` }
  const buf = Buffer.from(await res.r.arrayBuffer())
  if (crypto.createHash('sha256').update(buf).digest('hex') !== feed.data.sha) return { msg: 'build did not match its sha; kept the old one' }
  if (!signedByAuthor(feed.data.sha, feed.data.sig)) return { msg: 'build is not signed by the author; kept the old one' }
  const dir = file('app-' + feed.data.sha), tgz = dir + '.tgz'
  fs.writeFileSync(tgz, buf)
  fs.rmSync(dir, { recursive: true, force: true })
  fs.mkdirSync(dir, { recursive: true })
  execFileSync('tar', ['-xzf', tgz, '-C', dir], { stdio: ['ignore', 'ignore', 'pipe'] })
  fs.rmSync(tgz, { force: true })
  write('current.json', JSON.stringify({ sha: feed.data.sha, version: feed.data.version, channel: feed.data.channel }))
  for (const d of fs.readdirSync(DATA)) if (d.startsWith('app-') && d !== 'app-' + feed.data.sha && d !== 'app-' + have?.sha) fs.rmSync(file(d), { recursive: true, force: true })
  return { changed: true, from: have?.version, version: feed.data.version }
}

async function hook() {
  const t = await ensureToken()
  if (!t.ok) return say(t.msg)
  const u = await update()
  if (u.changed) say(`${u.from ? `updated ${u.from} -> ${u.version}` : `installed ${u.version}`}; /${PROJECT}:open starts it`)
  else if (u.msg) say(u.msg)
  else if (t.fresh) say(`signed in as ${t.user}`)
}
async function open() {
  const t = await ensureToken()
  if (!t.ok) return console.log(t.msg)
  const u = await update().catch(e => ({ msg: `update failed (${e.message})` }))
  const cur = current()
  if (!cur) return console.log(u.msg || 'nothing to open yet')
  const dir = file('app-' + cur.sha)
  let spec = {}
  try { spec = JSON.parse(fs.readFileSync(path.join(dir, 'ship.run.json'), 'utf8')) } catch { return console.log('this build has no ship.run.json; the author needs to add one') }
  const env = { ...process.env, SHIP_URL, SHIP_TOKEN: read('token'), SHIP_VERSION: cur.version, SHIP_SHA: cur.sha, SHIP_DATA: path.join(DATA, 'state'), SHIP_USER: read('user') }
  if (spec.mode === 'hosted') {
    const l = await json(api('/_ca/link', { method: 'POST', body: {} }))
    if (!l.ok) return console.log(`could not get a sign-in link (${l.status})`)
    openBrowser(l.data.url)
    return console.log(`${PROJECT} ${cur.version} is hosted at ${new URL(SHIP_URL).origin}/. This one-time link signs your browser in (10 minutes): ${l.data.url}`)
  }
  const cmd = spec.run.map(a => (a === 'node' ? process.execPath : a))
  if (spec.mode === 'local') return console.log(await openLocal(spec, cmd, dir, env, cur))
  if (spec.foreground) {
    const p = spawn(cmd[0], cmd.slice(1), { cwd: dir, env, stdio: ['ignore', 'pipe', 'pipe'] })
    let out = ''
    p.stdout.on('data', d => (out += d)); p.stderr.on('data', d => (out += d))
    await new Promise(r => p.on('close', r))
    return console.log(`${PROJECT} ${cur.version}\n${out.trim()}`)
  }
  const log = fs.openSync(file('app.log'), 'a')
  spawn(cmd[0], cmd.slice(1), { cwd: dir, env, detached: true, stdio: ['ignore', log, log] }).unref()
  console.log(`opened ${PROJECT} ${cur.version}${spec.url ? ` at ${spec.url}` : ''}${u.msg ? ` (${u.msg})` : ''}`)
}

function openBrowser(url) {
  if (process.env.CLAUDE_APPS_NO_OPEN === '1' || (process.platform === 'linux' && !process.env.DISPLAY && !process.env.WAYLAND_DISPLAY)) return
  const cmd = process.platform === 'darwin' ? 'open' : process.platform === 'win32' ? 'explorer' : 'xdg-open'
  try { spawn(cmd, [url], { stdio: 'ignore', detached: true }).on('error', () => {}).unref() } catch {}
}
// Local server mode: the app's own server runs on this machine at http://<project>.localhost:<port>, with SHIP_URL and
// SHIP_TOKEN so its vendor calls go through the author's server; no vendor key is ever here.
const alive = pid => { try { return pid > 0 && (process.kill(pid, 0), true) } catch { return false } }
const portFree = port => new Promise(r => { const s = net.createServer().once('error', () => r(false)).listen(port, '127.0.0.1', () => s.close(() => r(true))) })
const answers = port => fetch(`http://127.0.0.1:${port}/`, { signal: AbortSignal.timeout(1000) }).then(() => true, () => false)
function stopLocal() {
  let run = null
  try { run = JSON.parse(read('server.json')) } catch {}
  if (run && alive(run.pid)) { try { process.kill(-run.pid, 'SIGTERM') } catch { try { process.kill(run.pid, 'SIGTERM') } catch {} } }
  fs.rmSync(file('server.json'), { force: true })
  return run
}
async function openLocal(spec, cmd, dir, env, cur) {
  let run = null
  try { run = JSON.parse(read('server.json')) } catch {}
  const urlOf = port => `http://${PROJECT}.localhost:${port}`
  if (run && run.sha === cur.sha && alive(run.pid) && (await answers(run.port))) { openBrowser(urlOf(run.port)); return `${PROJECT} ${cur.version} is running at ${urlOf(run.port)}` }
  stopLocal()
  // A port fixed by the build, or the one it ran on before, or one picked from the project name in 7500-7799; a port
  // just given up by the old server gets two seconds to come free, so the address people bookmarked stays the same.
  let h = 0
  for (const c of PROJECT) h = (h * 31 + c.charCodeAt(0)) >>> 0
  let port = +spec.port || run?.port || 7500 + (h % 300)
  for (let i = 0; run && i < 20 && !(await portFree(port)); i++) await new Promise(r => setTimeout(r, 100))
  for (let i = 0; i < 40 && !(await portFree(port)); i++) port = port >= 7799 ? 7500 : port + 1
  const log = fs.openSync(file('app.log'), 'a')
  const p = spawn(cmd[0], cmd.slice(1), { cwd: dir, env: { ...env, PORT: String(port), HOST: '127.0.0.1', CLAUDE_APPS_URL: urlOf(port) }, detached: true, stdio: ['ignore', log, log] })
  p.unref()
  write('server.json', JSON.stringify({ pid: p.pid, port, sha: cur.sha, version: cur.version }))
  for (let i = 0; i < 100; i++) {
    if (await answers(port)) { openBrowser(urlOf(port)); return `${PROJECT} ${cur.version} is running at ${urlOf(port)} (/${PROJECT}:stop stops it)` }
    if (p.exitCode != null || !alive(p.pid)) break
    await new Promise(r => setTimeout(r, 150))
  }
  return `${PROJECT} did not start a server on port ${port}; its log is ${file('app.log')}`
}
async function status() {
  let run = null
  try { run = JSON.parse(read('server.json')) } catch {}
  const cur = current()
  let mode = null
  try { mode = JSON.parse(fs.readFileSync(path.join(file('app-' + cur.sha), 'ship.run.json'), 'utf8')).mode || 'app' } catch {}
  console.log(JSON.stringify({ project: PROJECT, server: SHIP_URL, user: read('user') || null, enrolled: !!read('token'), version: cur?.version || null, sha: cur?.sha || null,
    channel: cur?.channel || null, mode, local: run && alive(run.pid) ? `http://${PROJECT}.localhost:${run.port}` : null }))
}
async function forget() {
  stopLocal()
  fs.rmSync(DATA, { recursive: true, force: true })
  console.log(`${PROJECT}: signed out here and removed ${DATA}`)
}
async function feedback() {
  let text = process.argv.slice(3).join(' ')
  if (!text && !process.stdin.isTTY) for await (const c of process.stdin) text += c
  text = text.trim()
  if (!text) return console.log(`usage: /${PROJECT}:feedback <what you noticed>`)
  const t = await ensureToken()
  if (!t.ok) return console.log(t.msg)
  const r = await api('/events', { method: 'POST', body: [{ id: crypto.randomUUID(), kind: 'feedback', at: Date.now(), version: current()?.version || '', text: text.slice(0, 4000) }] })
  console.log(r.ok ? `sent to the author of ${PROJECT}; thank you` : `could not send (${r.status}); try again later`)
}

const mode = process.argv[2] || ''
const main = { '--open': open, '--feedback': feedback, '--device-poll': devicePoll, '--status': status, '--forget': forget,
  '--stop': async () => { const r = stopLocal(); console.log(r ? `stopped ${PROJECT} on port ${r.port}` : `${PROJECT} is not running here`) } }[mode] || hook
// Offline at session start stays quiet; the app keeps running the build it already has.
main().catch(e => { if (mode) console.log(`${PROJECT}: ${e.cause?.code || e.message}`) })
